import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600&display=swap`)
      .join("&")}`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ChatAnimationProps = Record<string, any>;

// Helper to estimate height of text blocks for accurate scroll calculations
const estimateHeight = (text: string) => {
  const charsPerLine = 35; 
  const lines = Math.ceil(text.length / charsPerLine);
  return lines * 53 + 64; 
};

// Sub-components
const ChatBubble: React.FC<{
  text: string;
  side: "left" | "right";
  top: number;
  scale: number;
  bg: string;
  color: string;
}> = ({ text, side, top, scale, bg, color }) => {
  const transformOrigin = side === "left" ? "bottom left" : "bottom right";
  const opacity = interpolate(scale, [0, 0.8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        top,
        left: side === "left" ? 60 : undefined,
        right: side === "right" ? 60 : undefined,
        maxWidth: "75%",
        backgroundColor: bg,
        color: color,
        padding: "32px 40px",
        borderRadius: 36,
        borderBottomLeftRadius: side === "left" ? 8 : 36,
        borderBottomRightRadius: side === "right" ? 8 : 36,
        fontSize: 38,
        lineHeight: 1.4,
        fontWeight: 400,
        transform: `scale(${scale})`,
        transformOrigin,
        opacity,
        boxShadow: "0 16px 40px rgba(0,0,0,0.05)",
        transition: "none",
        whiteSpace: "pre-wrap"
      }}
    >
      {text}
    </div>
  );
};

const TypingIndicator: React.FC<{
  top: number;
  scale: number;
  bg: string;
}> = ({ top, scale, bg }) => {
  const frame = useCurrentFrame();
  const opacity = interpolate(scale, [0, 0.8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const dot1 = interpolate(Math.sin(frame * 0.2), [-1, 1], [-5, 5]);
  const dot2 = interpolate(Math.sin((frame - 3) * 0.2), [-1, 1], [-5, 5]);
  const dot3 = interpolate(Math.sin((frame - 6) * 0.2), [-1, 1], [-5, 5]);

  return (
    <div
      style={{
        position: "absolute",
        top,
        right: 60,
        backgroundColor: bg,
        padding: "28px 36px",
        borderRadius: 36,
        borderBottomRightRadius: 8,
        transform: `scale(${scale})`,
        transformOrigin: "bottom right",
        display: "flex",
        gap: 12,
        alignItems: "center",
        opacity,
        boxShadow: "0 16px 40px rgba(0,0,0,0.05)",
        transition: "none",
      }}
    >
      <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: "#fff", transform: `translateY(${dot1}px)` }} />
      <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: "#fff", transform: `translateY(${dot2}px)` }} />
      <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: "#fff", transform: `translateY(${dot3}px)` }} />
    </div>
  );
};

const ChatAnimation: React.FC<ChatAnimationProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 10,
  message1 = "Did you hear about that girl getting paid by that guy? 😳",
  message2 = "Yeah girl… but we’re about to sit at a desk from 9–5 and be told what to do by a man for minimum wage.",
  message3 = "When you put it like that…",
  message4 = "Exactly.",
  senderBubbleColor = "#007AFF",
  receiverBubbleColor = "#E9E9EB",
  senderTextColor = "#FFFFFF",
  receiverTextColor = "#000000",
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout calculations
  const gap = 30;
  const H1 = estimateHeight(message1);
  const HT = 90; // Fixed typing indicator height estimate
  const H2 = estimateHeight(message2);
  const H3 = estimateHeight(message3);
  const H4 = estimateHeight(message4);

  // Absolute Y coordinates for each item
  const Y1 = 0;
  const YT = Y1 + H1 + gap;
  const Y2 = Y1 + H1 + gap;
  const Y3 = Y2 + H2 + gap;
  const Y4 = Y3 + H3 + gap;

  // Absolute bottom positions for the scroll calculations
  const B1 = Y1 + H1;
  const BT = YT + HT;
  const B2 = Y2 + H2;
  const B3 = Y3 + H3;
  const B4 = Y4 + H4;

  // Spring animations
  const springConf = { damping: 13, mass: 0.8, stiffness: 160 };
  const s1 = spring({ frame: frame - 20, fps, config: springConf });
  const sT_in = spring({ frame: frame - 70, fps, config: springConf });
  const sT_out = spring({ frame: frame - 120, fps, config: springConf });
  const s2 = spring({ frame: frame - 130, fps, config: springConf });
  const s3 = spring({ frame: frame - 200, fps, config: springConf });
  const s4 = spring({ frame: frame - 250, fps, config: springConf });

  // Calculate the accumulated bottom position to drive the smooth upward scroll
  const currentBottom =
    B1 * s1 +
    (BT - B1) * sT_in +
    (B1 - BT) * sT_out +
    (B2 - B1) * s2 +
    (B3 - B2) * s3 +
    (B4 - B3) * s4;

  // Anchor the chat to the lower part of the screen
  const anchorY = height * 0.75;
  const translateY = anchorY - currentBottom;

  const scaleT = Math.max(0, sT_in - sT_out);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter, sans-serif" }}>
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          transform: `translateY(${translateY}px)`,
          transition: "none",
        }}
      >
        <ChatBubble
          text={message1}
          side="left"
          top={Y1}
          scale={s1}
          bg={receiverBubbleColor}
          color={receiverTextColor}
        />
        
        {scaleT > 0.01 && (
          <TypingIndicator
            top={YT}
            scale={scaleT}
            bg={senderBubbleColor}
          />
        )}
        
        <ChatBubble
          text={message2}
          side="right"
          top={Y2}
          scale={s2}
          bg={senderBubbleColor}
          color={senderTextColor}
        />
        
        <ChatBubble
          text={message3}
          side="left"
          top={Y3}
          scale={s3}
          bg={receiverBubbleColor}
          color={receiverTextColor}
        />
        
        <ChatBubble
          text={message4}
          side="right"
          top={Y4}
          scale={s4}
          bg={senderBubbleColor}
          color={senderTextColor}
        />
      </div>
    </AbsoluteFill>
  );
};

export default ChatAnimation;